import { spawn } from 'node:child_process'
import { lstatSync, readdirSync, readFileSync, watch, writeFileSync } from 'node:fs'
import { join } from 'node:path'

// Passive fixture-side evidence capture. The original gate, arguments, validation and
// exit status are not replaced. Capture completed JSON if observed before success cleanup;
// on failure, the new gate helper independently retains its original report directory.
const root = '/evidence/tmp'
const directories = new Map()
const captured = new Set()
const observations = []
const errors = []
function capture(directory) {
  if (captured.has(directory)) return
  const path = join(directory, 'report.json')
  try {
    const stat = lstatSync(path)
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 16 * 1024 * 1024) return
    const bytes = readFileSync(path)
    const report = JSON.parse(bytes)
    if (!Number.isInteger(report.numTotalTests) || !Array.isArray(report.testResults)) return
    const output = `/evidence/observed-report-${observations.length}.json`
    writeFileSync(output, bytes, { flag: 'wx', mode: 0o600 })
    captured.add(directory)
    observations.push({ source: path, output, bytes: bytes.length, total: report.numTotalTests })
  } catch (error) {
    // Creation/write may still be in progress. A later event or child close retries capture.
    if (!['ENOENT', 'EISDIR'].includes(error.code) && !(error instanceof SyntaxError))
      errors.push(String(error))
  }
}
function discover() {
  for (const name of readdirSync(root)) {
    if (!name.startsWith('bazilion-security-acceptance-')) continue
    const directory = join(root, name)
    if (directories.has(directory)) continue
    try {
      const stat = lstatSync(directory)
      if (!stat.isDirectory() || stat.isSymbolicLink()) continue
      const watcher = watch(directory, () => capture(directory))
      watcher.on('error', (error) => errors.push(String(error)))
      directories.set(directory, watcher)
      capture(directory)
    } catch (error) {
      if (error.code !== 'ENOENT') errors.push(String(error))
    }
  }
}
const watcher = watch(root, discover)
watcher.on('error', (error) => errors.push(String(error)))
discover()
const child = spawn(process.execPath, ['scripts/security-acceptance.mjs'], { stdio: 'inherit' })
let spawnError
child.once('error', (error) => { spawnError = String(error) })
child.once('close', (code, signal) => {
  discover()
  for (const [directory, item] of directories) { capture(directory); item.close() }
  watcher.close()
  writeFileSync('/evidence/gate-result.json', JSON.stringify({ code, signal, spawnError, observations, errors }, null, 2))
  process.exitCode = signal || spawnError || code === null ? 1 : code
})
